import{_ as t,o,c as a,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"RFC 0088 — Mobile header and footer as Design System components","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign/blob/main/docs/rfcs/0088-mobile-header-footer-design-system-components.md"},"headers":[],"relativePath":"rfcs/0088-mobile-header-footer-design-system-components.md","filePath":"rfcs/0088-mobile-header-footer-design-system-components.md"}'),n={name:"rfcs/0088-mobile-header-footer-design-system-components.md"};function r(s,e,d,l,c,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="rfc-0088-—-mobile-header-and-footer-as-design-system-components" tabindex="-1">RFC 0088 — Mobile header and footer as Design System components <a class="header-anchor" href="#rfc-0088-—-mobile-header-and-footer-as-design-system-components" aria-label="Permalink to &quot;RFC 0088 — Mobile header and footer as Design System components&quot;">​</a></h1><p><strong>Status:</strong> Implemented<br><strong>Date:</strong> August 2026<br><strong>Author:</strong> kasunben<br><strong>Scope:</strong> <code>packages/ui</code> (new components), <code>runtime/app/(platform)/layout.tsx</code>, <code>runtime/app/(platform)/_components/MobileNav.tsx</code>, <code>runtime/app/(platform)/_components/ActivePluginTitle.tsx</code> (removed), <code>docs/design-system.md</code>, <code>docs/plugin-development.md</code>; builds on RFC 0013 (mobile responsiveness &amp; PWA — origin of the footer launcher pattern and the still-unwired &quot;active-plugin title&quot; concept this closes), RFC 0075 (per-plugin mobile header/footer visibility toggle, unchanged by this RFC), RFC 0079 (mobile PWA layout/gesture consistency — sibling <code>packages/ui</code> extraction precedent)<br><strong>Incorporated into plan:</strong> Yes — epic tasks 9.23, 9.24.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Extract the runtime&#39;s hardcoded mobile header and footer into two new <code>packages/ui</code> components — <strong><code>MobileHeader</code></strong> and <strong><code>MobileFooter</code></strong> — presentational and prop-driven, each with a small set of parts locked as immutable (the Sovereign/instance brand mark, the avatar menu, and the notification bell in the header; the centered &quot;Apps&quot; launcher in the footer) and a small set exposed as overridable (an optional header title; up to two additional icons on each side of the footer launcher). The runtime becomes the first — and for now, only — consumer, swapping its inline markup for these components with no behavior change. A header title that RFC 0013 described but never actually wired up was wired up during implementation, then deliberately reverted the same day (see &quot;UI flows&quot; and the Changelog) — so the shipped result is a like-for-like markup swap. This is deliberately scoped as groundwork: it does not design the mechanism by which a plugin might one day render this chrome itself, because that use case doesn&#39;t exist yet.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>Plugin developers have no way today to influence the mobile header or footer beyond RFC 0075&#39;s all-or-nothing visibility toggle — there is no reusable component, so a plugin wanting native-looking mobile chrome would have to hand-roll it, which is exactly what the DS-first rule (<code>docs/architecture-rules.md</code>) exists to prevent (&quot;reusable UI... is implemented in <code>packages/ui</code>... and consumed by plugins, never implemented plugin-locally &#39;to be promoted later&#39;&quot;). Extracting these two pieces of chrome now, before any concrete override use case is designed, lets the immutable/overridable boundary be drawn deliberately as a first step rather than retrofitted under the pressure of a specific plugin&#39;s request later.</p><p>Along the way, this closes a small existing gap: the mobile header&#39;s own doc comment has said &quot;brand · active-plugin title · bell · avatar menu&quot; since RFC 0013, but the component that was supposed to render that title (<code>ActivePluginTitle.tsx</code>) is never imported anywhere — dead code describing a feature that was never actually wired in.</p><h2 id="current-state-what-this-builds-on" tabindex="-1">Current state (what this builds on) <a class="header-anchor" href="#current-state-what-this-builds-on" aria-label="Permalink to &quot;Current state (what this builds on)&quot;">​</a></h2><ul><li><strong>Header</strong>, inline at <code>runtime/app/(platform)/layout.tsx:228-254</code>: a <code>&lt;Link href=&quot;/&quot;&gt;</code> brand (instance logo/monogram + <code>instanceName</code>, from white-labeling — RFC 0027/0032 — via <code>InstanceProvider</code>), followed by a right-hand cluster of <code>&lt;NotificationBell /&gt;</code> and <code>&lt;AccountMenu placement=&quot;header&quot; .../&gt;</code>. Both sub-components are also reused by the desktop sidebar.</li><li><strong><code>ActivePluginTitle.tsx</code></strong> (<code>runtime/app/(platform)/_components/</code>) — resolves the active plugin&#39;s name from the pathname via longest <code>routePrefix</code> match, meant to render as the header&#39;s contextual title per the RFC 0013 comment above. Confirmed orphaned: no import anywhere in the runtime except its own file.</li><li><strong>Footer</strong>, <code>runtime/app/(platform)/_components/MobileNav.tsx:49-83</code>: exactly three <code>nav</code> items — Home (left, plain link), the &quot;Apps&quot; launcher (center, opens a <code>Drawer</code> of installed plugins), Search (right, opens <code>MobileSearch</code>). One fixed center item, one left, one right — today&#39;s shape is already the &quot;1 fixed + 1 + 1&quot; case this RFC generalizes.</li><li><strong>Existing manifest hook is visibility-only</strong>: <code>shellConfig.mobileHeader</code>/<code>mobileFooter</code> booleans (RFC 0075, <code>packages/manifest/src/schema.ts:159-166</code>), both default <code>true</code>. Nothing lets a plugin influence header/footer <em>content</em> today; no real plugin currently sets either to <code>false</code> (confirmed — only test fixtures use it).</li><li><strong>No layout/shell component exists in <code>packages/ui</code></strong> today. Primitives like <code>PageContainer</code>, <code>Drawer</code>, <code>NavTabs</code> exist, but nothing for header or footer chrome. <code>packages/ui/src/stories/MobilePatterns.stories.tsx</code> documents the runtime&#39;s header/footer as reference material only (anatomy, 60px heights, the <code>--sv-shell-header-height</code> / <code>--sv-shell-footer-height</code> / <code>--sv-dialog-inset-top</code> tokens) — those token names are already a de facto public contract and must not change shape as part of this extraction.</li><li><strong>DS-first rule</strong> (<code>docs/design-system.md</code>, <code>docs/architecture-rules.md</code>): reusable UI/UX capability belongs in <code>packages/ui</code> or the runtime shell, never plugin-local. This RFC is a direct application of that rule to chrome that has, until now, only ever lived in the runtime.</li></ul><h2 id="proposed-design" tabindex="-1">Proposed design <a class="header-anchor" href="#proposed-design" aria-label="Permalink to &quot;Proposed design&quot;">​</a></h2><h3 id="mobileheader-packages-ui" tabindex="-1"><code>MobileHeader</code> (<code>packages/ui</code>) <a class="header-anchor" href="#mobileheader-packages-ui" aria-label="Permalink to &quot;`MobileHeader` (`packages/ui`)&quot;">​</a></h3><ul><li><strong>Locked (always rendered, not overridable):</strong><ul><li>A brand/logo slot — always renders and always links home. <code>packages/ui</code> doesn&#39;t know about instance identity or white-labeling, so this stays a prop (<code>logo: ReactNode</code>, <code>homeHref?: string</code>), with the runtime continuing to supply the resolved <code>instanceLogoUrl</code>/<code>instanceName</code> exactly as it does today.</li><li>A right-hand cluster that always renders a bell slot and an avatar-menu slot (<code>bell: ReactNode</code>, <code>avatarMenu: ReactNode</code>). <code>NotificationBell</code> and <code>AccountMenu</code> stay runtime-owned client components (they&#39;re bound to session/notification data) and are passed in as children, not reimplemented inside <code>packages/ui</code>.</li></ul></li><li><strong>Overridable:</strong><ul><li><code>title?: string</code> — renders next to the brand, absent by default (matching today&#39;s exact look when unset). The runtime wires this to a small hook that ports <code>ActivePluginTitle</code>&#39;s existing longest-prefix-match logic — this closes the RFC 0013 gap described above using the same resolution rule that was already designed and never connected, not new design.</li><li>Deliberately <strong>not</strong> built in this RFC: a search input in the header, floated in the original request as a possible future addition. No slot is reserved for it structurally — adding one later is additive.</li></ul></li></ul><h3 id="mobilefooter-packages-ui" tabindex="-1"><code>MobileFooter</code> (<code>packages/ui</code>) <a class="header-anchor" href="#mobilefooter-packages-ui" aria-label="Permalink to &quot;`MobileFooter` (`packages/ui`)&quot;">​</a></h3><ul><li><strong>Locked:</strong> one <strong>center</strong> slot, always the &quot;Apps&quot; launcher trigger (<code>onOpenApps: () =&gt; void</code>, <code>launcherIcon?: ReactNode</code>). The Drawer of installed plugins itself stays runtime-owned (it needs the live plugin list); <code>MobileFooter</code> renders the button and calls back.</li><li><strong>Overridable:</strong> <code>leftIcons</code> / <code>rightIcons</code> props, each accepting <strong>1 or 2</strong><code>FooterIcon</code> descriptors (<code>{ icon: ReactNode; label: string; href?: string; onClick?: () =&gt; void; active?: boolean }</code>). Symmetric by convention — 1+1 reproduces today&#39;s Home/Search layout exactly; 2+2 gives headroom for a 5-icon layout (3 fixed-shape slots × up to 2 each, in line with standard iOS/Android bottom-nav conventions of ≤5 items). The launcher stays visually centered regardless of which count is used; mismatched left/right counts are flagged with a dev-mode-only <code>console.error</code> (never thrown), the same non-fatal-guard pattern already used by <code>SwipableMobileCarousel</code>&#39;s non-<code>Slide</code>-children check.</li></ul><h3 id="runtime-wiring" tabindex="-1">Runtime wiring <a class="header-anchor" href="#runtime-wiring" aria-label="Permalink to &quot;Runtime wiring&quot;">​</a></h3><p><code>(platform)/layout.tsx</code> and <code>MobileNav.tsx</code> are refactored to render through <code>MobileHeader</code>/<code>MobileFooter</code>, passing exactly today&#39;s data through the new slot props. <code>ActivePluginTitle.tsx</code> is deleted; its resolution logic moves into a small runtime-local hook consumed by <code>layout.tsx</code>&#39;s title wiring (it needs the plugin registry, so it stays in the runtime, not <code>packages/ui</code>). No other behavior changes — this is a refactor plus one bug fix (the title finally rendering), not a redesign.</p><h3 id="explicitly-out-of-scope-deferred-to-a-future-rfc" tabindex="-1">Explicitly out of scope (deferred to a future RFC) <a class="header-anchor" href="#explicitly-out-of-scope-deferred-to-a-future-rfc" aria-label="Permalink to &quot;Explicitly out of scope (deferred to a future RFC)&quot;">​</a></h3><p>This RFC does <strong>not</strong> design a mechanism for a plugin to opt out of platform-rendered chrome and render its own equivalent using these components — that use case has not been introduced yet. Two concrete questions that mechanism would need to answer are recorded under Open questions below rather than resolved here, so they aren&#39;t reopened mid-design once a real trigger use case exists but also aren&#39;t lost.</p><h2 id="ui-flows" tabindex="-1">UI flows <a class="header-anchor" href="#ui-flows" aria-label="Permalink to &quot;UI flows&quot;">​</a></h2><p><strong>Navigating into any plugin</strong> — the header continues to show only the instance brand, exactly as before this RFC. The active-plugin-name title (the RFC 0013 behavior this RFC set out to finally wire up) was implemented during leg 2 and briefly rendered, then deliberately reverted the same day — showing the instance brand and plugin name side by side read oddly, and per-plugin titles turned out not to be the actual goal. The shipped result is a structurally-identical extraction with no user-visible change.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to &quot;Alternatives considered&quot;">​</a></h2><ol><li><strong>Wait to extract until the self-render use case is actually designed.</strong> Rejected — the DS-first rule already requires this content to live in <code>packages/ui</code>, not the runtime, once it&#39;s meant to be reusable; waiting also leaves the header-title dead code sitting unfixed indefinitely. Extracting now, while the future use case is still hypothetical, is a better moment to draw the immutable/overridable boundary deliberately rather than retrofit it under pressure from a specific plugin&#39;s ask.</li><li><strong>Make <code>MobileHeader</code>/<code>MobileFooter</code> self-fetching (SDK-aware) now</strong> — own their own notification-count/avatar data instead of taking it as props. Rejected: no current consumer needs it (the runtime already has this data server-side and passes it down), and it would be <code>packages/ui</code>&#39;s first &quot;smart,&quot; data-fetching component — a real precedent-setting decision that shouldn&#39;t be made speculatively before a self-rendering plugin actually exists to validate the shape.</li><li><strong>Design the full self-render opt-out mechanism in this RFC</strong> (manifest field semantics + data provisioning). Rejected per explicit scoping agreed before writing this RFC: there is no concrete trigger use case yet, and designing the mechanism now risks getting the manifest shape wrong before a real consumer can validate it.</li><li><strong>Allow asymmetric footer icon counts</strong> (e.g. two icons on the left, zero on the right). Rejected — breaks the one truly fixed visual constraint here, that the launcher stays centered.</li></ol><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to &quot;Open questions&quot;">​</a></h2><ol><li><strong>Semantics of a future self-render opt-out.</strong> When that use case is eventually designed: does it reuse <code>shellConfig.mobileHeader</code> / <code>mobileFooter: false</code> (which today means &quot;render nothing&quot;) to also mean &quot;I will reproduce this myself,&quot; or does it need a distinct value/field, since the two intents differ (no reserved layout space vs. reproducing it pixel-for-pixel)? No real plugin sets <code>false</code> today, so there&#39;s no live migration risk either way — this is purely a naming/semantics decision for whoever designs that follow-up.</li><li><strong>Data provisioning for a future self-rendering plugin.</strong> Would <code>MobileHeader</code>/<code>MobileFooter</code> need to become self-fetching at that point (contradicting Alternative 2&#39;s rejection above, but potentially justified once a real consumer exists), or would the SDK need new hooks (e.g. unread notification count, current user/avatar) so a self-rendering plugin can supply the same data as props the way the runtime does today? Left open — this RFC keeps both components presentational only.</li><li><strong>Header search input.</strong> Explicitly deferred to &quot;another phase&quot; per the original request; no structural slot reserved for it here.</li></ol><h2 id="adoption-path" tabindex="-1">Adoption path <a class="header-anchor" href="#adoption-path" aria-label="Permalink to &quot;Adoption path&quot;">​</a></h2><p>Documentation-first now; scheduled as epic tasks <strong>9.23</strong> (<code>packages/ui</code>: <code>MobileHeader</code>/<code>MobileFooter</code> components + Storybook coverage) and <strong>9.24</strong> (runtime: refactor <code>(platform)/layout.tsx</code> and <code>MobileNav.tsx</code> to consume them, delete <code>ActivePluginTitle.tsx</code>), sequenced by <a href="./../workstreams/0007-mobile-header-footer-extraction.html">Workstream 0007</a>. <code>@sovereignfs/ui</code> takes a <strong>minor</strong> bump (new, additive components); <code>runtime</code> takes a <strong>patch</strong> (internal refactor — the title-rendering fix was implemented and then reverted before shipping, so no runtime behavior actually changed). No manifest or SDK change in this RFC, so no <code>docs/upgrade.md</code> migration note is needed. The two Open questions above are the explicit gate for whatever future RFC introduces the plugin self-render use case — they do not block this one.</p><h2 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Date</th><th>Change</th></tr></thead><tbody><tr><td>0.1</td><td>Aug 2026</td><td>Initial draft</td></tr><tr><td>0.2</td><td>Aug 2026</td><td>Leg 1 implemented — <code>MobileHeader</code>/<code>MobileFooter</code> shipped in <code>packages/ui</code> (task 9.23, platform <code>0.62.0</code>).</td></tr><tr><td>0.3</td><td>Aug 2026</td><td>Leg 2 implemented — runtime consumes both components (task 9.24, platform <code>0.63.0</code>, <code>80f01fb</code>). The header-title wiring was built (<code>useActivePluginTitle</code> + <code>PlatformMobileHeader</code>) then deliberately reverted the same day (<code>1f35a95</code>) — brand and plugin name side by side read oddly, and per-plugin titles weren&#39;t the actual goal. Shipped runtime has no user-visible change. Status → Implemented.</td></tr></tbody></table>',29)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
